-- Recovery for a partial 00002 run on PostgreSQL versions without normalize(text, 'NFC').
create or replace function public.create_reading_passage(p_title text,p_content text,p_source_name text default null,p_source_url text default null,p_topik_level text default 'UNKNOWN',p_notes text default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare uid uuid:=auth.uid(); passage public.reading_passages; version public.reading_passage_versions;
begin if uid is null then raise exception 'Authentication is required'; end if; insert into reading_passages(user_id,title,source_name,source_url,topik_level,notes) values(uid,trim(p_title),p_source_name,p_source_url,p_topik_level,p_notes) returning * into passage; insert into reading_passage_versions(passage_id,version_number,content,content_hash,created_by) values(passage.id,1,p_content,md5(p_content),uid) returning * into version; update reading_passages set current_version_id=version.id where id=passage.id returning * into passage; return jsonb_build_object('passage',to_jsonb(passage),'version',to_jsonb(version)); end $$;
create or replace function public.create_reading_passage_version(p_passage_id uuid,p_content text) returns jsonb language plpgsql security definer set search_path=public as $$
declare uid uuid:=auth.uid(); passage public.reading_passages; version public.reading_passage_versions; next_number integer;
begin select * into passage from reading_passages where id=p_passage_id and user_id=uid for update; if not found then raise exception 'Passage not found'; end if; select coalesce(max(version_number),0)+1 into next_number from reading_passage_versions where passage_id=passage.id; insert into reading_passage_versions(passage_id,version_number,content,content_hash,created_by) values(passage.id,next_number,p_content,md5(p_content),uid) returning * into version; update reading_passages set current_version_id=version.id where id=passage.id returning * into passage; return jsonb_build_object('passage',to_jsonb(passage),'version',to_jsonb(version)); end $$;
create or replace function public.save_reading_word_to_set(p_version_id uuid,p_block_index integer,p_start_offset integer,p_end_offset integer,p_selected_text text,p_sentence_context text,p_lemma text,p_part_of_speech text,p_meaning_vi text,p_context_meaning_vi text,p_pronunciation text,p_morphemes jsonb,p_grammar_note_vi text,p_confidence text,p_provider text,p_provider_version text,p_study_set_id uuid,p_term text,p_meaning text,p_reuse_flashcard_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare uid uuid:=auth.uid(); version public.reading_passage_versions; passage public.reading_passages; annotation public.reading_annotations; card public.flashcards; block_text text; next_order integer;
begin select v.* into version from reading_passage_versions v join reading_passages p on p.id=v.passage_id where v.id=p_version_id and p.user_id=uid; if not found then raise exception 'Reading version not found'; end if; select * into passage from reading_passages where id=version.passage_id; if p_start_offset<0 or p_end_offset<=p_start_offset or char_length(p_selected_text) not between 1 and 40 then raise exception 'Invalid annotation range'; end if; block_text:=(regexp_split_to_array(version.content,E'\\n\\s*\\n'))[p_block_index+1]; if block_text is null or substring(block_text from p_start_offset+1 for p_end_offset-p_start_offset)<>p_selected_text then raise exception 'Selection does not match passage content'; end if; if not exists(select 1 from study_sets s where s.id=p_study_set_id and s.user_id=uid) then raise exception 'Study set not found'; end if; insert into reading_annotations(user_id,passage_id,passage_version_id,block_index,start_offset,end_offset,selected_text,sentence_context,lemma,part_of_speech,meaning_vi,context_meaning_vi,pronunciation,morphemes,grammar_note_vi,confidence,analysis_provider,analysis_provider_version) values(uid,passage.id,version.id,p_block_index,p_start_offset,p_end_offset,p_selected_text,p_sentence_context,p_lemma,p_part_of_speech,p_meaning_vi,p_context_meaning_vi,p_pronunciation,coalesce(p_morphemes,'[]'::jsonb),p_grammar_note_vi,p_confidence,p_provider,p_provider_version) returning * into annotation; if p_reuse_flashcard_id is not null then select f.* into card from flashcards f join study_sets s on s.id=f.study_set_id where f.id=p_reuse_flashcard_id and s.user_id=uid; if not found then raise exception 'Flashcard not found'; end if; else perform 1 from study_sets where id=p_study_set_id for update; select coalesce(max(order_index),-1)+1 into next_order from flashcards where study_set_id=p_study_set_id; insert into flashcards(study_set_id,term,meaning,order_index) values(p_study_set_id,p_term,p_meaning,next_order) returning * into card; end if; insert into reading_flashcard_links(annotation_id,flashcard_id) values(annotation.id,card.id); return jsonb_build_object('annotation',to_jsonb(annotation),'flashcard',to_jsonb(card),'passage',jsonb_build_object('id',passage.id,'title',passage.title)); end $$;
revoke all on function public.create_reading_passage(text,text,text,text,text,text),public.create_reading_passage_version(uuid,text),public.save_reading_word_to_set(uuid,integer,integer,integer,text,text,text,text,text,text,text,jsonb,text,text,text,text,uuid,text,text,uuid) from public;
grant execute on function public.create_reading_passage(text,text,text,text,text,text),public.create_reading_passage_version(uuid,text),public.save_reading_word_to_set(uuid,integer,integer,integer,text,text,text,text,text,text,text,jsonb,text,text,text,text,uuid,text,text,uuid) to authenticated;
